#include <cstdio>
#include <cstdlib>
#include <vector>
typedef std::vector<unsigned int> Big; // base 1e9, little-endian
static Big add(const Big& a, const Big& b) {
    Big r;
    unsigned long long carry = 0;
    for (size_t i = 0; i < a.size() || i < b.size() || carry; i++) {
        unsigned long long s = carry;
        if (i < a.size()) s += a[i];
        if (i < b.size()) s += b[i];
        r.push_back((unsigned int)(s % 1000000000ULL));
        carry = s / 1000000000ULL;
    }
    return r;
}
int main(int argc, char** argv) {
    long n = argc > 1 ? atol(argv[1]) : 0;
    Big a(1, 1), b(1, 1);
    for (long i = 0; i < n; i++) {
        Big c = add(a, b);
        a = b;
        b = c;
    }
    printf("%u", a.back());
    for (size_t i = a.size() - 1; i-- > 0;) printf("%09u", a[i]);
    printf("\n");
    return 0;
}
